package ktanesolver.module.modded.regular.necronomicon;import static org.assertj.core.api.Assertions.assertThat;import java.util.List;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.SolveSuccess;
class NecronomiconSolverTest{@Test void selectsTheFirstEligiblePriorityChapter(){ModuleEntity m=new ModuleEntity();@SuppressWarnings("unchecked")NecronomiconOutput o=((SolveSuccess<NecronomiconOutput>)new NecronomiconSolver().solve(new RoundEntity(),new BombEntity(),m,new NecronomiconInput("Plateau of Leng","Azathoth","true name",List.of(8,7,6,5,4,3,2)))).output();assertThat(o.chapter()).isEqualTo(2);assertThat(o.page()).isEqualTo(1);assertThat(o.command()).isEqualTo("page 1");assertThat(m.getState()).containsEntry("necronomiconChapters",List.of(2,3,4,5,6,7,8));}}
